select
id, user_id, resume_id, ai_base_id, ai_resume_id, operation_type, prompt, result, create_time, update_time
from resume_ai_operation


        and id = #{id}


        and user_id = #{userId}


        and resume_id = #{resumeId}


        and ai_base_id = #{aiBaseId}


        and ai_resume_id = #{aiResumeId}


        and operation_type = #{operationType}


        and prompt = #{prompt}


        and result = #{result}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

